<script setup lang="ts">
import {computed,ref} from 'vue'
import {formatMoney} from './v6Format'
import ModelCurve from './ModelCurve.vue'
import type {V6Model} from './v6Types'
const props=defineProps<{model?:V6Model|null}>()
const fmt=(value:number|null|undefined,d=0)=>value==null?'—':value.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const pct=(value:number|null|undefined)=>value==null?'—':`${value>0?'+':''}${fmt(value,2)}%`
const points=(value:number|null|undefined)=>value==null?'—':`${value>0?'+':''}${fmt(value,0)} 點`
const tone=(value:number|null|undefined)=>value==null?'neutral':value>0?'gain':value<0?'loss':'neutral'
const isCross=computed(()=>props.model?.strategy_key==='v6-2')
const showAll=ref(false)
const recent=computed(()=>{const all=[...(props.model?.trades||[])].reverse();return showAll.value?all:all.slice(0,20)})
const series=computed(()=>isCross.value?[{key:'v6-2',label:'V6-2 · 65分／冷卻2日',color:'#426f61',curve:props.model?.curve||[]}]:[{key:'v6',label:'65 分',color:'#aa5975',curve:props.model?.curve||[]},
 {key:'v6_70',label:'70 分觀察',color:'#b59648',curve:props.model?.observation70?.curve||[]}])
const sourceLabels:Record<string,string>={vix:'VIX',feargreed:'恐懼貪婪',twd:'美元／台幣',oil:'油價',spx:'美股',financial:'金融ETF',electronics:'電子ETF',tsm:'台積電ADR','rates-proxy':'美債殖利率',foreign:'外資台指期部位',retail:'小台散戶比',cpi_calendar:'CPI公告日期',tsmc_calendar:'台積電法說日期',index_close:'最新加權指數收盤'}
const sourceName=(key:string)=>sourceLabels[key]||key
const reason=(value:string)=>({stop:'停損',gap_stop:'跳空停損',profit:'停利',gap_profit:'跳空停利',time:'持有日數到期'}[value]||value)
</script>

<template>
 <section class="v6-panel">
  <header><div><small>{{isCross?'V6-2 · 主策略':'原V6 · 歷史模型'}}</small><h2>{{isCross?'價格、外資與跨資產 · 台指期純空':'宏觀與籌碼風險觀察'}}</h2><p v-if="isCross">65分門檻 · 跌深8%不追空 · 出場冷卻{{model?.cooldown_days}}日。以下績效與交易均來自同一份V6-2回放，不與原V6混算。</p><p v-else>65 與 70 分並行觀察同一套進出場，交易規則以本份保存紀錄下方說明為準，兩者不互相改寫。本區數據隨上方人工研究紀錄一同保存。</p></div></header>
  <p class="research-note">{{model?.warning||'研究設定尚未通過穩定勝率驗證。'}}</p>
  <p v-if="model?.status==='failed'" class="note error">{{model.error||'V6 資料暫時無法計算'}}</p>
  <template v-else-if="model?.as_of">
   <div class="signal"><div><small v-if="isCross">行情截至 {{model.as_of}} · 模擬保存 {{model.generated_at?.slice(0,16).replace('T',' ')}}</small><small v-else>指數行情 {{model.as_of}} · 台灣 {{model.decision_at?.slice(0,16).replace('T',' ')}} 決策</small><strong>{{model.next_action}}</strong><span>加權指數 {{fmt(model.index_close,2)}} · 觀察契約 {{model.target_contract}} · 目前 {{model.position===-1?'持有空單':'空手'}}</span></div><div class="score"><small>{{isCross?'末日歷史分數／觀察線':'風險分數／觸發線'}}</small><b>{{model.readiness==='ready'&&model.score!=null?fmt(model.score,1):'等待確認'}} <span>/ {{model.score_threshold||65}}</span></b><small>分數並非下跌機率</small></div></div>
   <div v-if="!isCross" class="observations"><article><small>65 分原設定</small><strong>{{model.readiness!=='ready'?'等待資料':model.entry_allowed?'下一交易日觀察進場':model.signal?'達標，依持倉與冷卻規則判斷':'未達進場條件'}}</strong><span>{{model.wins}} 勝／{{model.completed}} 筆 · 一口 {{points(model.pnl_points)}}</span></article><article><small>70 分並行觀察</small><strong>{{model.readiness!=='ready'?'等待資料':model.observation70?.entry_allowed?'下一交易日觀察進場':model.observation70?.signal?'達標，依持倉與冷卻規則判斷':'未達進場條件'}}</strong><span>{{model.observation70?.wins}} 勝／{{model.observation70?.completed}} 筆 · 一口 {{points(model.observation70?.pnl_points)}}</span></article></div>
   <p v-if="model.missing_sources?.length||model.missing_tx_dates?.length" class="note error">缺少完整資料：{{[...(model.missing_sources||[]).map(sourceName),...(model.missing_tx_dates||[])].join('、')}}。目前不發出新訊號。</p>
   <div class="metrics"><article><small>{{model.period}} 名目報酬</small><b :class="tone(model.portfolio_return_pct)">{{pct(model.portfolio_return_pct)}}</b><span>{{points(model.pnl_points)}} · 固定一口約 NT$ {{formatMoney(model.pnl_twd_per_contract)}}</span></article><article><small>已完成交易勝率</small><b>{{model.hit_rate==null?'—':fmt(model.hit_rate,1)+'%'}}</b><span>{{model.wins||0}} 勝／{{model.completed||0}} 筆</span></article><article><small>持有中防線</small><b>{{model.position===-1?fmt(model.stop)+' 點':'目前空手'}}</b><span>{{model.position===-1?'停利 '+fmt(model.take)+' 點 · 停損 '+fmt(model.stop)+' 點':'沒有待觸發的空單停損'}}</span></article><article><small>歷史最大回撤</small><b :class="tone(model.max_drawdown_pct)">{{pct(model.max_drawdown_pct)}}</b><span>{{isCross?'最大點數回撤 '+fmt(model.max_drawdown_points)+' 點':'一口名目點數評價'}}</span></article></div>
   <div class="curve-head"><h3>{{isCross?'V6-2 累積績效':'原V6 累積績效'}}</h3><p v-if="isCross">固定一口空單；曲線包含未平倉收盤評價並扣成本。歷史重新回放，沒有補登成當時交易；名目報酬不是保證金報酬。</p><p v-else>65 與 70 分各自獨立模擬一口空單；曲線包含未平倉評價。70 分歷史交易很少，勝率不能當未來保證。</p></div>
   <ModelCurve :series="series" unit="%"/>
   <p v-if="isCross" class="note">{{model.basis}}</p><p v-else class="note">訊號綜合 VIX、恐懼貪婪、匯率、油價、美債殖利率、美股／台積電 ADR、金融相對電子走勢、RSI、已公布的 CPI 與法說日期；以本地歷史選出較弱月份。利率、戰爭與傳產輪動只使用上述價格代理。{{model.basis}}</p>
   <div class="trades"><div class="trade-heading"><h3>{{isCross?'V6-2 歷史回放交易':'最近完成的空單'}} · {{recent.length}}／{{model.trades?.length||0}} 筆</h3><button v-if="(model.trades?.length||0)>20" type="button" @click="showAll=!showAll">{{showAll?'只看最近20筆':'顯示全部交易'}}</button></div><div class="scroll"><table><thead><tr><th>訊號日／分數</th><th>進場日／點位</th><th>出場日／點位</th><th v-if="isCross">訊號日回落幅度</th><th>原因</th><th>持有</th><th>扣成本損益</th></tr></thead><tbody><tr v-for="t in recent" :key="t.entry_date+'-'+t.contract"><td>{{t.signal_date}}<small>{{fmt(t.signal_score,1)}} 分</small></td><td>{{t.entry_date}}<small>{{fmt(t.entry)}} 點 · {{t.contract}}</small></td><td>{{t.exit_date}}<small>{{fmt(t.exit)}} 點</small></td><td v-if="isCross">{{fmt(t.signal_drawdown_pct,2)}}%</td><td>{{reason(t.reason)}}</td><td>{{t.held}} 日</td><td :class="tone(t.points)">{{points(t.points)}}<small>約 NT$ {{formatMoney(t.pnl_twd)}}</small></td></tr><tr v-if="!recent.length"><td :colspan="isCross?7:6">尚無已完成空單。</td></tr></tbody></table></div></div>
   <footer>{{isCross?'本區只呈現已保存的V6-2歷史回放；不會因重整、前台更新或排程重新計算，對話要求更新V6時才保存新版本。原V6保留獨立查閱。':'V6 研究設定曾用歷史跌段探索；正式頁面僅提供固定規則的模擬觀察。新資料必須在台灣時間 08:30 前取得。'}}夜盤風險及跳空可能使實際損益與日K回測不同。</footer>
  </template>
 </section>
</template>

