;background:#f3f7f2;color:#426f61;cursor:pointer}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:12px 9px;border-bottom:1px solid #e9eee8;text-align:right;white-space:nowrap}th{background:#f5f7f3;color:#748170}th:first-child,td:first-child{text-align:left}td small{display:block;color:#94a092;margin-top:3px}footer{padding:14px 24px;background:#fafbf8;color:#859080;font-size:12px;line-height:1.6}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.v6-panel>header,.signal{flex-direction:column;align-items:flex-start}.score{text-align:left}.metrics{grid-template-columns:1fr}}
.observations{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-bottom:1px solid #edf0ea}.observations article{padding:15px 24px}.observations article+article{border-left:1px solid #edf0ea}.observations small,.observations span{display:block;font-size:12px;color:#788374}.observations strong{display:block;font-size:15px;color:#495848;margin:6px 0}@media(max-width:620px){.observations{grid-template-columns:1fr}.observations article+article{border-left:0;border-top:1px solid #edf0ea}}
